window.STORY_CHAPTERS["c68f6d85aed769d3b"]={"id":"c68f6d85aed769d3b","lines":[{"uid":"talk.rushin_2105_short_novel_17_4#originalText","id":"talk.rushin_2105_short_novel_17_4","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"然后，就是……","en":"So, I, uh…","ja":"それで、その……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_5#originalText","id":"talk.rushin_2105_short_novel_17_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请说！","en":"Yes?","ja":"はい!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_6#originalText","id":"talk.rushin_2105_short_novel_17_6","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"其实我今天下午休假……妳呢？","en":"I happen to be free this afternoon... What about you?","ja":"実は、今日の午後は休みをもらったんだけど……君は?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_7#originalText","id":"talk.rushin_2105_short_novel_17_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"训练在上午就结束了，所以我下午没有任何事。","en":"I'm free. I took care of my training earlier this morning.","ja":"訓練は午前中に終わったので、何もありません"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_8#originalText","id":"talk.rushin_2105_short_novel_17_8","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"这样啊……真、真巧耶。","en":"Oh... Wh-What a coincidence.","ja":"そっか……き、奇遇だね"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_9#originalText","id":"talk.rushin_2105_short_novel_17_9","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是、是啊……","en":"Y-Yes…","ja":"は、はい……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_10#originalText","id":"talk.rushin_2105_short_novel_17_10","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"方便的话，要不要一起……去吃个饭？当然，妳不愿意的话就算了！","en":"So, maybe we could eat dinner...together? Only if you don't mind!","ja":"……よかったら、でいいんだけど、どこかで食事でもどうか……な?もちろん、嫌だったらいいんだけど!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_11#originalText","id":"talk.rushin_2105_short_novel_17_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我是不介意……但是真的可以吗？","en":"I don't mind. But...is it really okay, for someone like me to join you?","ja":"嫌ではありません……がよろしいのですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_12#originalText","id":"talk.rushin_2105_short_novel_17_12","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"当、当然啰！我很想跟妳一起去吃饭！","en":"O-Of course! I want to go with you!","ja":"も、もちろん!君と行きたいんだ!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_13#originalText","id":"talk.rushin_2105_short_novel_17_13","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊，那个、这……","en":"Oh! I mean, I…","ja":"あっ、そのこれは……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_17_14#originalText","id":"talk.rushin_2105_short_novel_17_14","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……呵呵，我明白了。请让我陪您一起用餐吧！","en":"Hehe. I understand. I'd be honored to dine with you.","ja":"……ふふ、了解しました。お食事ご一緒させていただきます!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_0#originalText","id":"talk.rushin_2105_short_novel_18_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.6 『迪索尔巴德讲师的特训』","en":"After WoU, vol. 6: Master Deusolbert's Training","ja":"After WoU vol.6 『デュソルバート師範の特訓』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_18_1#originalText","id":"talk.rushin_2105_short_novel_18_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"日前的大乱，妳们的表现可圈可点，但相对来说，修行尚嫌不足。","en":"Your skills awakened during the war, but you still need training!","ja":"先の大乱では、お主たちの働きは目覚ましかっただが、一方でまだまだ修行が足りぬ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_2#originalText","id":"talk.rushin_2105_short_novel_18_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"是！","en":"Yes, sir!","ja":"はいっ!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_3#originalText","id":"talk.rushin_2105_short_novel_18_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"因此，接下来将进行锻炼身心的修行。妳们每天都要勤加练习，不能间断。","en":"To that end, I would like to begin daily mind and body training.","ja":"よって、これからは心身を鍛えるための修業を行う毎日欠かさず励むように"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_4#originalText","id":"talk.rushin_2105_short_novel_18_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"了、了解！","en":"Y-Yes, sir!","ja":"りょ、了解しました!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_5#originalText","id":"talk.rushin_2105_short_novel_18_5","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"首先是《端坐无想》的修行。妳们在那里坐下。","en":"First, meditation class. Sit there, girls. Backs straight.","ja":"まずは《端坐無想》の修業であるふたりとも、そこに座るように"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_6#originalText","id":"talk.rushin_2105_short_novel_18_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好的……这样吗？","en":"Yes, sir... Like this?","ja":"はい……こうですか"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_7#originalText","id":"talk.rushin_2105_short_novel_18_7","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"《端坐无想》是面对自身心意的修行。要心无杂念，凝视自己的心灵深处。","en":"Meditation trains you to face your Incarnation. It empties the mind and helps you find yourself.","ja":"《端坐無想》は、自らの心、心意と向き合うための修業である心を無にし、己の心の裡を見つめるように"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_8#originalText","id":"talk.rushin_2105_short_novel_18_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"心无杂念，凝视自己的……","en":"Empty my mind... Find myself…","ja":"心を無にして、己の……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_9#originalText","id":"talk.rushin_2105_short_novel_18_9","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_10#originalText","id":"talk.rushin_2105_short_novel_18_10","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"单纯闭上眼睛不算是修行，妳们要面对自己的心灵。","en":"Merely shutting the eyes does nothing. Face your inner self.","ja":"ただ目をつむるだけでは、修行にならぬ己の心と向き合うのだ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_11#originalText","id":"talk.rushin_2105_short_novel_18_11","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……我不太明白那是怎么样的状态……","en":"But...how does that feel? I don't really understand.","ja":"……それって、どんな状態なんですかよくわからなくて……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_12#originalText","id":"talk.rushin_2105_short_novel_18_12","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"继续做下去就会懂了。别说话，继续。","en":"You'll come to understand the more you practice. Continue.","ja":"続けるうちにわかってくる黙って続けよ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_18_13#originalText","id":"talk.rushin_2105_short_novel_18_13","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"好、好的！真是非常抱歉，讲师阁下！","en":"Y-Yes, sir! Forgive my hesitation, Sir Deusolbert!","ja":"は、はい!申し訳ありませんでした、師範閣下!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_0#originalText","id":"talk.rushin_2105_short_novel_19_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.7 『桐人返回修剑学院』","en":"After WoU, vol. 7: Kirito's Return to Swordcraft Academy","ja":"After WoU vol.7 『キリト、修剣学院への帰還』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_19_1#originalText","id":"talk.rushin_2105_short_novel_19_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"明明才过不到一年，却莫名觉得好怀念耶。所谓母校就是这种感觉吗？","en":"After only a year, it feels like ages ago... Is this what visiting school as an OB feels like?","ja":"まだ一年も経ってないのに、なんだか懐かしいな卒業した学校って、こんな感じなのか"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_2#originalText","id":"talk.rushin_2105_short_novel_19_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"好久不见了，桐人。","en":"It has been a while, Kirito.","ja":"久しぶりですね、キリト"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_3#originalText","id":"talk.rushin_2105_short_novel_19_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"阿滋利卡老师！好久不见了！","en":"Ms. Azurica! So good to see you again!","ja":"アズリカ先生!ご無沙汰してます!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_4#originalText","id":"talk.rushin_2105_short_novel_19_4","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我听说你曾倒下后就一直很担心……但你现在看来很有精神，真是太好了。","en":"I heard you were ill...but I'm relieved to see that you're well again.","ja":"一度倒れた、と聞いてから心配していましたが……元気そうですね、何よりです"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_5#originalText","id":"talk.rushin_2105_short_novel_19_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是的，我已经完全康复了。抱歉让您担心了。","en":"Yes, I'm all back to normal. Thanks for your concern.","ja":"ええ、もうすっかり元気ですご心配をおかけしました"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_6#originalText","id":"talk.rushin_2105_short_novel_19_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，对不起，我把罗妮耶跟缇洁都带去了我们那边……","en":"Oh, pardon me, I hope it was okay that I took Ronie and Tiese to the Cathedral…","ja":"あ、すみませんロニエとティーゼを、こっちに連れてきちゃって……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_7#originalText","id":"talk.rushin_2105_short_novel_19_7","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"那种情况下也是在所难免。","en":"Given the circumstances, it couldn't be helped.","ja":"あのような状況であれば、仕方ないでしょう"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_8#originalText","id":"talk.rushin_2105_short_novel_19_8","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……她们两个都过得好吗？","en":"But how have the girls been?","ja":"……あのふたりは元気ですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_9#originalText","id":"talk.rushin_2105_short_novel_19_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是的，她们都过得很好。多亏有她们在，帮了很大的忙喔！","en":"Very well, thank you! They've both been of great help!","ja":"はい、すごく元気だし、彼女たちのおかげですごく助かってますよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_10#originalText","id":"talk.rushin_2105_short_novel_19_10","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"这样啊，那就好。……你可要好好照顾她们喔。","en":"Well, I'm glad to hear that. Make sure you cherish them.","ja":"そうですか、それはよかった……くれぐれも、大事にしてあげてくださいね"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_19_11#originalText","id":"talk.rushin_2105_short_novel_19_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是，我当然会的！","en":"Yes, ma'am. Of course I will!","ja":"はい、もちろんです!"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_0#originalText","id":"talk.rushin_2105_short_novel_20_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"After WoU vol.8 『翱翔天空的龙』","en":"After WoU, vol. 8: Flying Dragon","ja":"After WoU vol.8 『空飛ぶ竜』"},"kind":"caption"},{"uid":"talk.rushin_2105_short_novel_20_1#originalText","id":"talk.rushin_2105_short_novel_20_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哇啊，好可爱！这是龙的小宝宝对吧。","en":"Aww, what a cutie! So this is a baby dragon.","ja":"うわあ、かわいい!これが竜の赤ちゃんなのね"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_2#originalText","id":"talk.rushin_2105_short_novel_20_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"是的，今后我们会亲自养育，最终乘上成为骑龙的牠。","en":"Yes, we're going to raise it into a dragon we can fly on someday.","ja":"はい、これから私たちが育てて、やがて騎竜として乗ることになります"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_3#originalText","id":"talk.rushin_2105_short_novel_20_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这孩子居然会成长得那么巨大呢……Underworld真是有意思。","en":"This baby is going to get that big... Underworld sure is fun.","ja":"この子が、あんなに大きくなるなんて……アンダーワールドは面白いわね"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_4#originalText","id":"talk.rushin_2105_short_novel_20_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"亚丝娜大人跟桐人学长的世界没有龙吗？","en":"Are there no dragons in your world, Lady Asuna?","ja":"アスナ様やキリト先輩の世界には、竜はいないのですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_5#originalText","id":"talk.rushin_2105_short_novel_20_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这个嘛……远古时代是有种叫做《恐龙》的爬虫类啦……","en":"No. Though we did have reptiles called \"dinosaurs\" in the past.","ja":"そうね、遠い昔に《恐竜》という爬虫類はいたけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_6#originalText","id":"talk.rushin_2105_short_novel_20_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"这样的话，每个人都是用走路或骑马来移动吗？","en":"So, does everyone walk or ride horses to get around?","ja":"だとしたら、みなさんは徒歩や馬で移動するんですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_7#originalText","id":"talk.rushin_2105_short_novel_20_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在我们出生以前好像是。不过，现在可能是依靠汽车或电车比较多。","en":"Long before we were born, yes. But now, we have trains and cars.","ja":"わたしたちが生まれる前には、そうだったみたいでも、今は自動車とか電車が多いかも"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_8#originalText","id":"talk.rushin_2105_short_novel_20_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"汽车……？","en":"Karz...?","ja":"じどうしゃ……"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_9#originalText","id":"talk.rushin_2105_short_novel_20_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"两种都是利用电力来驱动的机器交通工具喔。电力……或许有点类似神圣术。","en":"They both run on electricity. It's kind of like Sacred Arts, really.","ja":"どちらも、電気の力で走る機械の乗り物ね電気は、神聖術と似てるかも"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_10#originalText","id":"talk.rushin_2105_short_novel_20_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"原来如此……桐人学长之前提过翱翔天空的机器龙，也是像这样吗？","en":"Interesting... Maybe it's like that flying machine Kirito mentioned.","ja":"なるほど……キリト先輩がこの間話していた、空飛ぶ機械の竜もそんな感じなのですか"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_11#originalText","id":"talk.rushin_2105_short_novel_20_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"对，的确很像呢。","en":"Yes, it is definitely similar.","ja":"そうね、確かに似ているわ"},"kind":"dialogue"},{"uid":"talk.rushin_2105_short_novel_20_12#originalText","id":"talk.rushin_2105_short_novel_20_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好厉害喔……机器居然会飞在空中，或是像马一样奔驰啊……","en":"Wow... Just imagine, machines that can fly or race like horses.","ja":"すごいですね……機械が空を飛んだり、馬のように走ったりするなんて"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_0#originalText","id":"talk.rushin_2108_short_novel_21_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.1 『克莱因的迦具土探索』","en":"Daily Life in ALO, vol. 1: Klein's Search for Kagutsuchi","ja":"ALOの日常 vol.1 『クラインのカグツチ探索』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_21_1#originalText","id":"talk.rushin_2108_short_novel_21_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"阿桐啊，我今天一定要拖你陪我去寻找《灵刀迦具土》。","en":"Hey, K-dawg, today's the day you're helping me find the Spirit Katana Kagutsuchi.","ja":"キリの字よう、今日こそは《霊刀カグツチ》探すの付き合ってもらうぜ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_2#originalText","id":"talk.rushin_2108_short_novel_21_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你嘴上这么说，其实是期待能再遇见湖之女王大人那样的人吧？","en":"Aren't you just hoping you'll run into someone like the Queen of the Lake?","ja":"そんなこと言って、また湖の女王様みたいな人と会うのを期待しているんじゃないのか?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_3#originalText","id":"talk.rushin_2108_short_novel_21_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你、你胡说什么啊！","en":"D-Don't be silly!","ja":"ば、バカ言うんじゃねぇよ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_4#originalText","id":"talk.rushin_2108_short_novel_21_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"与迦具土有关的日本神话里，可没有出现美女姊妹之类的喔。","en":"In Japanese lore, the stories of Kagutsuchi involve no hot ladies whatsoever.","ja":"カグツチ関連の日本神話には美女姉妹なんて出てこないぞ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_5#originalText","id":"talk.rushin_2108_short_novel_21_5","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"所以我就说不是那样了！","en":"So that's got nothing to do with this!","ja":"だから、そんなんじゃねぇっての!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_6#originalText","id":"talk.rushin_2108_short_novel_21_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真是的……那你找齐成员了吗？","en":"Jeez... Anyway, do you have your team yet?","ja":"まったく……で、メンツはそろえたのか?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_7#originalText","id":"talk.rushin_2108_short_novel_21_7","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"这倒是还没啦。通常先约你之后，很快就会凑齐人了对吧？所以……","en":"Not yet. But everyone'll flock to me if you're on the team, sooo…","ja":"それがまだなんだよおめぇが誘えばあっという間に集まるだろ?　だから……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_8#originalText","id":"talk.rushin_2108_short_novel_21_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"什么啊，你至少先把人找齐吧。成员到齐了再来谈。","en":"Hey, at least assemble your team first before you contact me.","ja":"なんだよ、せめてメンツ集めくらいはやっておいてくれ話はそれからだ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_9#originalText","id":"talk.rushin_2108_short_novel_21_9","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"喂、喂！桐人！哪有这样的啊！","en":"O-Oh come on, Kirito! Don't give me that!","ja":"お、おいキリト!そりゃねぇだろ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_10#originalText","id":"talk.rushin_2108_short_novel_21_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……唉，如果不是要攻略迷宫，只是一般打怪的话，我是可以奉陪啦。","en":"Well, I guess I'll come... As long as it's a hunt and not a dungeon.","ja":"……まあ、ダンジョン攻略じゃなくて、普通の狩りだったら付き合ってやるけど"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_21_11#originalText","id":"talk.rushin_2108_short_novel_21_11","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"哦，真拿你没办法耶。这次就我们两个结伴吧！","en":"Heh. You never change, do ya? Guess it's just the two of us for this one!","ja":"おう、しょうがねぇな今回は、ふたりで行くとすっか!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_0#originalText","id":"talk.rushin_2108_short_novel_22_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.2 『三明治的回忆』","en":"Daily Life in ALO, vol. 2: Sandwich Memories","ja":"ALOの日常 vol.2 『サンドイッチの思い出』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_22_1#originalText","id":"talk.rushin_2108_short_novel_22_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们总算有这一天了呢。","en":"Ahh, we finally made it.","ja":"やっと、ここにたどり着いたね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_2#originalText","id":"talk.rushin_2108_short_novel_22_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"是啊……跟那时候一模一样。","en":"Yeah... Nothing's changed.","ja":"ああ……あの時のまんまだな"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_3#originalText","id":"talk.rushin_2108_short_novel_22_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"是的，和我第一次见到爸爸妈妈的时候……一模一样呢！","en":"Yes, everything is just as it was when I first met you!","ja":"はい、パパとママに初めて会った時と……おんなじです!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_4#originalText","id":"talk.rushin_2108_short_novel_22_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"总觉得买到房子安心下来后，就气力尽失呢。","en":"For some reason, now that we've bought the house, I'm exhausted.","ja":"なんだか、お家を買えたらホッとして力が抜けちゃった"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_5#originalText","id":"talk.rushin_2108_short_novel_22_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样的话，换我来煮饭。","en":"I'll do the cooking then.","ja":"だったら、俺が料理を作るよ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_6#originalText","id":"talk.rushin_2108_short_novel_22_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人你要下厨？","en":"You? Cook?","ja":"キリトくんが料理?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_7#originalText","id":"talk.rushin_2108_short_novel_22_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"因为我有个点子。","en":"I've got an idea I want to try.","ja":"ちょっと考えがあるんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_8#originalText","id":"talk.rushin_2108_short_novel_22_8","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我好期待呢，爸爸！","en":"I can't wait, Daddy!","ja":"楽しみです、パパ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_9#originalText","id":"talk.rushin_2108_short_novel_22_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人，这不是……","en":"Kirito... Is that...?","ja":"キリトくん、これって……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_10#originalText","id":"talk.rushin_2108_short_novel_22_10","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"跟那时候一样呢，爸爸。我说要跟爸爸吃一样的那个……","en":"It's just like that time I asked for the same thing as Daddy…","ja":"あの時と同じです、パパ私が、パパと同じがいいって言った……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_11#originalText","id":"talk.rushin_2108_short_novel_22_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"三明治的话，就算是我也做得出来嘛。而且有确实加上超辣酱料喔。","en":"I figured I could make sandwiches. And I put on the super hot sauce.","ja":"サンドイッチなら、俺でも作れるからなちゃーんと激辛ソースだぞ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_12#originalText","id":"talk.rushin_2108_short_novel_22_12","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"哇啊……我开动了！","en":"Ooh... Thank you!","ja":"うわあ……いただきます!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_22_13#originalText","id":"talk.rushin_2108_short_novel_22_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，真的好像回到了那一天呢。","en":"Hehe. It really is just like old times.","ja":"ふふ、本当にあの日に戻ったみたいだね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_0#originalText","id":"talk.rushin_2108_short_novel_23_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.3 『亚丝娜与艾基尔的新菜单开发』","en":"Daily Life in ALO, vol. 3: Asuna and Agil's New Menu","ja":"ALOの日常 vol.3 『アスナとエギルの新メニュー開発』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_23_1#originalText","id":"talk.rushin_2108_short_novel_23_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"艾基尔先生，谢谢你。你店里明明很忙，我还占用你的时间。","en":"Thanks for making time for me, Agil. I know you're busy.","ja":"エギルさん、ありがとうお店お忙しいのに、時間とってもらっちゃって"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_2#originalText","id":"talk.rushin_2108_short_novel_23_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"没什么，晚上交给我老婆顾店就行了。不过我倒是有点惊讶妳指名要找我。","en":"No worries. My wife takes care of the café at night. I'm surprised you sought me out, though.","ja":"なに、夜は妻に任せておけば心配ないだが、オレを指名ってのは、少々びっくりしたよ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_3#originalText","id":"talk.rushin_2108_short_novel_23_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"其实我想设计新的菜单，而现实世界里最会做菜的就是艾基尔先生了，对吧？","en":"Well, I want to create a new menu. You're the best cook I know in real life.","ja":"実は、新しいお料理のメニューを作りたいんです現実世界で、一番料理が上手なのはエギルさんでしょ?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_4#originalText","id":"talk.rushin_2108_short_novel_23_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"毕竟我是靠这一行吃饭的嘛。原来如此，这样的话我很乐意帮忙。","en":"Well, it is how I make my living. Okay, I think I can help you there.","ja":"まあオレは商売でやってるからななるほど、そういうことなら力になろう"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_5#originalText","id":"talk.rushin_2108_short_novel_23_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"太好了～因为最近客人很多，我已经快想不出菜色变化了。","en":"Yay! We've had a lot of guests recently, and my repertoire is lacking.","ja":"よかったー最近お客様が多くて、レパートリーが尽きてきちゃったから"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_6#originalText","id":"talk.rushin_2108_short_novel_23_6","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"真是太令人羡慕了，我也好想说说看这句话啊。","en":"I wish I had your problem.","ja":"うらやましい限りだオレもそんなこと言ってみたいもんだよ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_7#originalText","id":"talk.rushin_2108_short_novel_23_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"哎呀，但是艾基尔先生的店感觉总是高朋满座耶……","en":"Oh? But the Dicey Café is always packed.","ja":"あら、エギルさんのお店、いつも混んでると思うけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_8#originalText","id":"talk.rushin_2108_short_novel_23_8","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"那是因为你们来的时候总是一大群人。总之开始吧，有哪些材料？","en":"Yeah, when you guys are there. Anyway, let's start. Do you have ingredients?","ja":"あんたたちが来るときは、だいたい大勢だからなとにかく、始めよう。材料は何があるんだ?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_9#originalText","id":"talk.rushin_2108_short_novel_23_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"啊，有这些。这附近钓得到鱼，所以我想说鱼类料理应该不错……","en":"Yes. I was thinking of fish dishes, since there are so many lakes here.","ja":"あ、これですこの辺りは魚が取れるから、魚料理がいいなって……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_10#originalText","id":"talk.rushin_2108_short_novel_23_10","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"好，那就每种都来做一遍看看吧。在这里下厨也是满开心的。","en":"Okay, let's give it a try. I do enjoy cooking in-game, too.","ja":"よし、じゃあ一通り作ってみるかこっちで料理するのも、結構楽しいからな"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_23_11#originalText","id":"talk.rushin_2108_short_novel_23_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就是说啊～！那就麻烦你了，艾基尔先生。","en":"Me too! Thanks, Agil. You're a lifesaver.","ja":"そうですよねー!頼りにしてます、エギルさん"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_0#originalText","id":"talk.rushin_2108_short_novel_24_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.4 『朔夜的偷跑』","en":"Daily Life in ALO, vol. 4: Sakuya's Preemtive Strike","ja":"ALOの日常 vol.4 『サクヤのヌケガケ』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_24_1#originalText","id":"talk.rushin_2108_short_novel_24_1","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"嗨，桐人！欢迎来到风精灵领地！","en":"Hey, Kirito! Welcome to Sylph territory!","ja":"やあ、キリト君!ようこそシルフ領へ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_2#originalText","id":"talk.rushin_2108_short_novel_24_2","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"不过，不选在司伊鲁班真的没关系吗？明明那里也有适合用来招待你的客房。","en":"Would you have preferred Swilvane? I had a perfect room for you.","ja":"しかし、スイルベーンじゃなくて本当に良かったのか?君を迎えるにふさわしい客室もあったのに"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_3#originalText","id":"talk.rushin_2108_short_novel_24_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没关系啦，我比较喜欢像这样的地方……","en":"No, it's cool. I prefer this sort of place.","ja":"いや、俺はこういう場所の方が好きなんで……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_4#originalText","id":"talk.rushin_2108_short_novel_24_4","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"原来如此……桐人比较喜欢野外……","en":"Interesting... So you an outdoorsy kind of guy. Noted.","ja":"なるほど……キリト君は野外がお好き、と"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_5#originalText","id":"talk.rushin_2108_short_novel_24_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呃，请问到底是怎么回事？妳好像在做笔记……","en":"Um, are you taking notes or something?","ja":"あの、いったい何ですか?今メモみたいなの……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_6#originalText","id":"talk.rushin_2108_short_novel_24_6","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"哦，这你别在意。听我说，我拿到了很珍贵的酒喔。","en":"Oh, don't mind me. Anyway, I've got some pretty rare wine.","ja":"ああ、気にしないでくれそれより、レアものの酒が手に入ったんだ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_7#originalText","id":"talk.rushin_2108_short_novel_24_7","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"口感温醇甘甜，不敢喝酒的人也能容易入口。来，你尝尝！","en":"It's so sweet that even wine-haters like it. Drink up!","ja":"口当たりが甘くて、酒が苦手な人でもスッと飲める。さあ、どうぞ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_8#originalText","id":"talk.rushin_2108_short_novel_24_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，那……我就不客气了。……啊，真好喝。","en":"Oh, uh, thanks... Ooh. It's good.","ja":"あ、それじゃ……いただきます……あ、うまい"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_9#originalText","id":"talk.rushin_2108_short_novel_24_9","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"对吧？来，也有下酒菜……","en":"I know, right? Have some snacks, too.","ja":"そうだろう?さあ、つまみも……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_10#originalText","id":"talk.rushin_2108_short_novel_24_10","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"啊──朔夜妳果然偷跑了！","en":"Sakuya, I knew it! You're doing a preemptive strike!","ja":"あー、やっぱりサクヤちゃんヌケガケしてる!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_11#originalText","id":"talk.rushin_2108_short_novel_24_11","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"露！？妳已经发现了吗！？","en":"Rue?! You've already sniffed out my grand scheme?!","ja":"ルー!?もう嗅ぎ付けてきたのか!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_12#originalText","id":"talk.rushin_2108_short_novel_24_12","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"真是的，对妳完全不能掉以轻心呢！","en":"Sheesh, can't turn my back on you for an instant!","ja":"まったく、油断も隙も無いんだから!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_24_13#originalText","id":"talk.rushin_2108_short_novel_24_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_0#originalText","id":"talk.rushin_2108_short_novel_25_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.5 『亚丽莎的偷跑』","en":"Daily Life in ALO, vol. 5: Alicia's Preemptive Strike","ja":"ALOの日常 vol.5 『アリシャのヌケガケ』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_25_1#originalText","id":"talk.rushin_2108_short_novel_25_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好，今天我要钓个够！一整天不受任何人打扰，悠悠哉哉……","en":"Okay, let's get a big catch today! I can just relax, alone, and…","ja":"さあ、今日は釣るぞ!一日誰にも邪魔されず、ゆっくり……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_2#originalText","id":"talk.rushin_2108_short_novel_25_2","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"找……到了！","en":"Founnnd...you!","ja":"見ぃ……つけた!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_3#originalText","id":"talk.rushin_2108_short_novel_25_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呜哇！？是、是谁！！","en":"Whoa?! Wh-Who's there?!","ja":"うわっ!?だ、誰だ!!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_4#originalText","id":"talk.rushin_2108_short_novel_25_4","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"咦～你忘记了吗？是我啊，是我！","en":"Aww, did you forget who I am? It's me. Me!","ja":"えー、忘れちゃったの?あたしだよ、あたし!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_5#originalText","id":"talk.rushin_2108_short_novel_25_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"亚丽莎小姐……妳怎么会在这？","en":"Alicia... What are you doing here?","ja":"アリシャさん……どうしてここに?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_6#originalText","id":"talk.rushin_2108_short_novel_25_6","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"因为我得到情报，说你一个人跑来这里啊～","en":"I received intelligence that you'd be here alone!","ja":"ここに、キミがひとりで来るって情報を入手したからだヨー"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_7#originalText","id":"talk.rushin_2108_short_novel_25_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那么，妳找我有什么事吗？","en":"So...what do you want?","ja":"それで、どんな用事なんですか?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_8#originalText","id":"talk.rushin_2108_short_novel_25_8","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"我只是很想见你啊～不可以吗？","en":"I wanted to see youuu. That okay?","ja":"キミに会いたかっただけダヨーダメかな?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_9#originalText","id":"talk.rushin_2108_short_novel_25_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这……我是不介意啦……","en":"Well...I guess so.","ja":"それは、かまいませんけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_10#originalText","id":"talk.rushin_2108_short_novel_25_10","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"呵呵呵呵呵，你可以就这样把我钓上钩也没关系唷……","en":"Hehehehehe. Good, good. Keep luring me in like that…","ja":"ふふふふふ、その調子で、あたしのことを釣り上げちゃってもいい……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_11#originalText","id":"talk.rushin_2108_short_novel_25_11","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"什么叫「把我钓上钩也没关系」啊！","en":"Keep luring me in, like hell!","ja":"なにが「釣り上げちゃってもいい」、だ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_12#originalText","id":"talk.rushin_2108_short_novel_25_12","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"呃，朔夜！","en":"Agh! Sakuya!","ja":"げっ、サクヤちゃん!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_25_13#originalText","id":"talk.rushin_2108_short_novel_25_13","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"受不了，对妳真是大意不得……","en":"Sheesh, I can't turn my back on you for an instant…","ja":"まったく、油断も隙も無いなお前は……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_0#originalText","id":"talk.rushin_2108_short_novel_26_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.6 『莉法与桐人，两人独处』","en":"Daily Life in ALO, vol. 6: Leafa and Kirito's Moment Alone","ja":"ALOの日常 vol.6 『リーファとキリトがふたりっきり』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_26_1#originalText","id":"talk.rushin_2108_short_novel_26_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你好──","en":"Hello!","ja":"こんにちはー"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_2#originalText","id":"talk.rushin_2108_short_novel_26_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……呼啊……睡得真饱。啊，莉法，早安。","en":"Ahh, what a good sleep. Oh, good morning, Leafa.","ja":"……ふわあ、よく寝たあ、リーファ。おはよう"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_3#originalText","id":"talk.rushin_2108_short_novel_26_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"还说什么早安啊。你今天睡到中午耶。","en":"It's not \"morning,\" idiot. You've slept right past noon.","ja":"おはよう、じゃないよ今日、お昼まで寝てたよね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_4#originalText","id":"talk.rushin_2108_short_novel_26_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"是说，只有你一个人吗？亚丝娜小姐呢？","en":"And wait, is it just you? Where's Asuna?","ja":"というか、キリト君ひとり?アスナさんは"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_5#originalText","id":"talk.rushin_2108_short_novel_26_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，亚丝娜去沉睡骑士那里了。其他人好像也都在忙。","en":"She's with the Sleeping Knights. They're busy with something.","ja":"ああ、アスナはスリーピング・ナイツの方に行ってるみんなも忙しいみたいだな"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_6#originalText","id":"talk.rushin_2108_short_novel_26_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"就我跟桐人两人独处！？","en":"So it's just you and me?!","ja":"あたしとキリト君のふたりきり!?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_7#originalText","id":"talk.rushin_2108_short_novel_26_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这、这样啊──是这样子啊……","en":"O-Ohhh... That's interesting.","ja":"そ、そっかーそうなんだあ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_8#originalText","id":"talk.rushin_2108_short_novel_26_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么了，莉法？妳好像怪怪的喔。","en":"What's up, Leafa? You're acting weird.","ja":"どうしたんだ、リーファなんかおかしいぞ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_9#originalText","id":"talk.rushin_2108_short_novel_26_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我、我哪有怪怪的啦。……那我们去外面晃晃吧。","en":"N-No, I'm not acting weird! Hey...let's head out for a bit.","ja":"お、おかしくなんかないよ……ねえ、じゃあちょっと外に行こうよ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_10#originalText","id":"talk.rushin_2108_short_novel_26_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"去外面晃晃啊……说得对，一直睡觉也不太好。","en":"Outside... Okay. Sleeping all day would be lazy of me.","ja":"外か……そうだな、ずっと寝てるのもアレだし"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_11#originalText","id":"talk.rushin_2108_short_novel_26_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嗯，走吧！我们好久没玩那个了，来玩吧。","en":"Yeah, let's go! And let's do that thing we used to do.","ja":"うん、行こう!久しぶりにさ、アレやろうよ、アレ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_12#originalText","id":"talk.rushin_2108_short_novel_26_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"看谁先飞到终点的比赛！","en":"That flying race, remember?","ja":"どっちが先にゴールまで飛べるかってヤツ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_26_13#originalText","id":"talk.rushin_2108_short_novel_26_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哦，是妳提出来的喔。这次我可不会输的！","en":"Oh, it's on! I'm not losing this time!","ja":"お、言ったな今度は負けないぞ!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_0#originalText","id":"talk.rushin_2108_short_novel_27_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.7 『个性相像的两人1』","en":"Daily Life in ALO, vol. 7: Peas in a Pod 1","ja":"ALOの日常 vol.7 『似た者同士1』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_27_1#originalText","id":"talk.rushin_2108_short_novel_27_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"欸，桐人，到底要怎么做才能使出那个斩掉魔法的招式啊？","en":"Hey, Kirito, how do you use your sword to deflect magic spells?","ja":"ねえ、キリトあの魔法を斬るヤツ、どうやったらできるの?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_2#originalText","id":"talk.rushin_2108_short_novel_27_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我也办得到吗～？","en":"Think I can do it too?","ja":"ボクにもできるかなあ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_3#originalText","id":"talk.rushin_2108_short_novel_27_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"原理很简单，因为魔法也是沿着轨道飞过来的，所以只要斩断轨道就好。","en":"It's pretty straightforward. Spells fly along set trajectories, so you have to cut through them.","ja":"原理は簡単だよ魔法も軌道に沿って飛んでくるから、それを斬るだけだ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_4#originalText","id":"talk.rushin_2108_short_novel_27_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过，我会有办法做到，或许是因为我在《GGO》都盯着子弹看的关系。","en":"But the reason I can do it is probably because I did it in GGO, just with bullets.","ja":"ただ、俺ができるようになったのは、《GGO》で銃の弾丸を見てるからかもしれないなあ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_5#originalText","id":"talk.rushin_2108_short_novel_27_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"一般人才不会想到这种事呢。大家都是做好承受魔法伤害的准备在战斗。","en":"You know, most people wouldn't even consider it. We just assume we'll get hit with magic damage.","ja":"普通の人は、あんなこと考えないわよ魔法ダメージを計算に入れて、戦うんだから"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_6#originalText","id":"talk.rushin_2108_short_novel_27_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"可是啊，要是没受到魔法伤害，不就能跟更强的敌人战斗了吗！？","en":"But without that damage, you'd be able to fight even stronger enemies, right?!","ja":"でもさ、そのダメージがなかったとしたらもっと強い敵とも戦えるよね!?"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_7#originalText","id":"talk.rushin_2108_short_novel_27_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"如果下一个头目是魔法系怪物的话，铁定就能派上用场了！","en":"I'm sure it'll come in handy if the next boss is a magic user!","ja":"次のボスが、魔法系だったりしたら、役に立つよきっと!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_8#originalText","id":"talk.rushin_2108_short_novel_27_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"假如有纪想试试，我是可以教妳啦……","en":"If you want to learn, I can try to teach you, Yuuki…","ja":"ユウキがやってみたいなら、教えてもいいけど……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_9#originalText","id":"talk.rushin_2108_short_novel_27_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嗯，我想试试看！","en":"Yeah, I wanna try!","ja":"うん、ボクやってみたい!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_27_10#originalText","id":"talk.rushin_2108_short_novel_27_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真是的，你们两个……真的很像耶！","en":"Jeez, you two... You really are like peas in a pod!","ja":"まったく、ふたりとも……ほんと、似た者同士なんだから!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_0#originalText","id":"talk.rushin_2108_short_novel_28_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.8 『个性相像的两人2』","en":"Daily Life in ALO, vol. 8: Peas in a Pod 2","ja":"ALOの日常 vol.8 『似た者同士2』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_28_1#originalText","id":"talk.rushin_2108_short_novel_28_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"诗乃，危险！","en":"Sinon, watch out!","ja":"シノン、危ない!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_2#originalText","id":"talk.rushin_2108_short_novel_28_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"唔……！","en":"Mmf!","ja":"くっ……!"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_3#originalText","id":"talk.rushin_2108_short_novel_28_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我说诗乃……刚才那是……","en":"Sinon... What was that...?","ja":"なっ……シノン、今の……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_4#originalText","id":"talk.rushin_2108_short_novel_28_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你不是用剑斩断过魔法吗？既然这样，我能用弓箭抵销魔法也不奇怪吧？","en":"You can cut magic spells with your sword, right? So I figured I could do the same with arrows.","ja":"あんた、魔法を剣で斬ったんでしょう?だとしたら、矢で相殺できるのも不思議じゃないじゃない"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_5#originalText","id":"talk.rushin_2108_short_novel_28_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"可是，用剑击中跟用弓箭射中的难度……","en":"But they're much easier to hit with a sword than an arrow…","ja":"でも、剣を当てるのと矢を当てるのじゃ難易度が……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_6#originalText","id":"talk.rushin_2108_short_novel_28_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽说我头一次在实战中成功就是了。练习时成功概率大概是一半一半。","en":"Well, that was the first time I've done it in battle. Right now, it's about 50-50 in practice.","ja":"まあ、実戦での成功は初めてだけどね練習では五分五分ってところかな"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_7#originalText","id":"talk.rushin_2108_short_novel_28_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦？妳之前也试过吗？那还真是……","en":"Huh? You've been testing it out all this time? That's pretty hardcore…","ja":"えっ、今までも試してたのか?それはずいぶん……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_8#originalText","id":"talk.rushin_2108_short_novel_28_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你可没资格说我喔。之前取回《断钢圣剑》时，我抓到了诀窍。","en":"You're one to talk. I got the hang of it when I caught Excalibur.","ja":"あんたに言われたくないわよこの前、《エクスキャリバー》をキャッチしたとき、コツをつかんだのよ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_9#originalText","id":"talk.rushin_2108_short_novel_28_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"弓箭比想像中还要容易控制呢。","en":"Arrows are surprisingly easy to control.","ja":"案外、コントロールできるものね、弓矢って"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_10#originalText","id":"talk.rushin_2108_short_novel_28_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不不不……妳那与其说是控制……","en":"\"Easy to control\"...? You can't be serious…","ja":"いやいや……コントロールって……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_28_11#originalText","id":"talk.rushin_2108_short_novel_28_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……毕竟我也不能输给你啊。","en":"Just so you know... I won't let you outshine me.","ja":"……あんたには、負けられないからね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_0#originalText","id":"talk.rushin_2108_short_novel_29_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"ALO的日常 vol.9 『Girls' Talk』","en":"Daily Life in ALO, vol. 9: Girl Talk","ja":"ALOの日常 vol.9 『ガールズトーク』"},"kind":"caption"},{"uid":"talk.rushin_2108_short_novel_29_1#originalText","id":"talk.rushin_2108_short_novel_29_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"对了，Augma就快发售了耶。","en":"Oh, hey, I just remembered. The Augma is about to launch, isn't it?","ja":"そういえば、もうすぐ発売ですね、オーグマー"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_2#originalText","id":"talk.rushin_2108_short_novel_29_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"就是啊～应该也会推出不少游戏，真令人期待。","en":"Ooh, that's right. I can't wait. So many new games!","ja":"そうだねーゲームも結構出るんだよね、楽しみ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_3#originalText","id":"talk.rushin_2108_short_novel_29_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"AR的RPG应该是在现实世界里战斗吧？这样子，剑道会不会派上用场呢……","en":"AR RPGs take place in the real world, right? You think kendo will be useful?","ja":"ARのRPGって、リアル世界で戦うんですよねだとしたら、剣道が役に立つかなあ"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_4#originalText","id":"talk.rushin_2108_short_novel_29_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"对耶，妳有在练剑道。这样的话应该很强吧。","en":"That's right, you do kendo. You'll be a powerhouse, then.","ja":"そっか、リーファさんは剣道やってるんですよねだったら強そう"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_5#originalText","id":"talk.rushin_2108_short_novel_29_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我们在现实世界里根本不行呢。虽说这一点桐人跟亚丝娜也是一样啦。","en":"Stuff set in real life is no good for us. Well, same for Kirito and Asuna.","ja":"あたしたちは、リアルの方は全然だもんねまあそれはキリトとかアスナもだけど"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_6#originalText","id":"talk.rushin_2108_short_novel_29_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我经常叫桐人再多练点剑道，但是他根本听不进去。","en":"I keep telling Kirito to practice kendo more, but he won't listen.","ja":"キリト君には、もっと剣道やろうっていつも言ってるんですけどね全然聞いてくれないの"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_7#originalText","id":"talk.rushin_2108_short_novel_29_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"毕竟那家伙根本已经活在VR里了嘛……","en":"Yeah, he practically lives in VR now.","ja":"あいつは、もう完全にVRで生きてるからなあ……"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_8#originalText","id":"talk.rushin_2108_short_novel_29_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呵呵，不过他就是这点很棒呢。","en":"Hehe, though that's part of his charm.","ja":"ふふ、そういうところが、ステキですけどね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_9#originalText","id":"talk.rushin_2108_short_novel_29_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"……也是啦。","en":"I guess so.","ja":"……まあね"},"kind":"dialogue"},{"uid":"talk.rushin_2108_short_novel_29_10#originalText","id":"talk.rushin_2108_short_novel_29_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真是的，妳们都太宠他了！亚丝娜小姐也是……得对他更严厉点才行啦！","en":"You guys are too soft on him! So's Asuna...but come on, work with me!","ja":"もう、ふたりとも甘やかしすぎです!アスナさんもだけど……もっと厳しくしないと!"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_0#originalText","id":"talk.rushin_2111_short_novel_30_0","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"艾恩葛朗特的回忆 vol.1 『黑色剑士与情报商人』","en":"Aincrad Memories, vol. 1: Black Swordsman and Intel Broker","ja":"アインクラッドの思い出 vol.1 『黒の剣士と情報屋』"},"kind":"caption"},{"uid":"talk.rushin_2111_short_novel_30_1#originalText","id":"talk.rushin_2111_short_novel_30_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"亚鲁戈……那件事查得如何了？这是给妳的情报费。","en":"Argo... How did you go? Here's the fee, as usual.","ja":"アルゴ……どうだ、例の話はこれ、情報料だ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_2#originalText","id":"talk.rushin_2111_short_novel_30_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"多谢惠顾。如果是指那个任务，目前还没有人成功喔。","en":"Pleasure, as always. So, about the info you requested: no one's been successful yet.","ja":"毎度アリ例のクエストなら、まだ成功者は出てないヨ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_3#originalText","id":"talk.rushin_2111_short_novel_30_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"好像已经有很多队伍前去挑战，但别说是目标金属了，连材料都不常出现。","en":"Lots of parties are attacking, but no metals, no materials, nothin'.","ja":"ずいぶん色んなパーティがアタックしてるみたいだけどネ目当ての金属どころか、素材もロクに出ないみたいダヨ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_4#originalText","id":"talk.rushin_2111_short_novel_30_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"原来如此……这任务该不会是捏造的？","en":"Huh... Maybe it's just a hoax?","ja":"なるほどな……もしかしてガセなのか?"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_5#originalText","id":"talk.rushin_2111_short_novel_30_5","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"就我所知目前没有真正的假任务。即便像假情报，也应有某种理由跟结果。","en":"There's been no dummy-quests that I know of. Even if the info's fake, there's something there.","ja":"オレっちの知る限り、完全なダミークエストは今まで存在しない偽情報っぽくても、なんらかの理由や決着がついてるはずダヨ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_6#originalText","id":"talk.rushin_2111_short_novel_30_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"照妳这么说，就是缺少了某个关键啰……","en":"Which means...we're probably missing a piece of the puzzle.","ja":"となると、なにかのピースが足りないってことか……"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_7#originalText","id":"talk.rushin_2111_short_novel_30_7","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"……你要小心啊，桐人小子。对手是只龙，而且第55层可是雪山。","en":"Hey, you be careful now, Kii-boy. It's a dragon, and on the 55th Floor, no less.","ja":"……気を付けなよ、キー坊相手はドラゴンだし、55層は雪山だからナ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_8#originalText","id":"talk.rushin_2111_short_novel_30_8","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"除非准备了够好的装备或是获得了可靠的情报，不然会很艰辛喔。","en":"It'll be a tough quest if ya don't have the proper equipment and intel.","ja":"そうとう装備を整えるか、確定情報を入手してからじゃないと厳しいと思うヨ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_9#originalText","id":"talk.rushin_2111_short_novel_30_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我知道。就算是我，也不会毫无把握就去挑战的。","en":"I know. Even I'm not dumb enough to take it on unprepared.","ja":"ああ、いくら俺でもアテのないうちはチャレンジしないよ"},"kind":"dialogue"},{"uid":"talk.rushin_2111_short_novel_30_10#originalText","id":"talk.rushin_2111_short_novel_30_10","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"……是这样就好啰。那就这样啦，拜拜，桐人小子。","en":"I sure hope not... Well, see ya later, Kii-boy.","ja":"……だといいんだけどネそれじゃ、またな、キー坊"},"kind":"dialogue"},{"uid":"talk.rushin_2204_campaign_1_1#originalText","id":"talk.rushin_2204_campaign_1_1","speaker":{"cn":"魔王桐人","en":"Demon Lord Kirito"},"text":{"cn":"这世界上所有的LA奖励和宝箱，","en":"All the LA Bonuses and treasures of this world","ja":"この世の全てのLAボーナス、そして宝箱は"},"kind":"dialogue"},{"uid":"talk.rushin_2204_campaign_1_2#originalText","id":"talk.rushin_2204_campaign_1_2","speaker":{"cn":"魔王桐人","en":"Demon Lord Kirito"},"text":{"cn":"全都是属于本大爷的！","en":"belong to me now!","ja":"全てこの俺様のものだ!"},"kind":"dialogue"},{"uid":"talk.rushin_2204_campaign_1_3#originalText","id":"talk.rushin_2204_campaign_1_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"才不会让你得逞！","en":"Over my dead body!","ja":"そんなこと、させるものか!"},"kind":"dialogue"},{"uid":"talk.rushin_2204_campaign_1_4#originalText","id":"talk.rushin_2204_campaign_1_4","speaker":{"cn":"魔王桐人","en":"Demon Lord Kirito","ja":"魔王キリト"},"text":{"cn":"有趣……那就来试试看吧，看妳能否阻止本大爷的野心。","en":"Amusing... If you think you can thwart me, then be my guest.","ja":"面白い……我が野望を阻止できるかやってみるがよい"},"kind":"dialogue"}]};
